      CALL1(DEPUTY, record);
    CALL3(PANEL_MESSAGE, ds[ACTIVE_SIDE], 2, text);
    put_word(ds, (uint16_t)(SIDE_ROUTED + ds[ACTIVE_SIDE] * 2), 1);
