    opeu_copy_bytes(ds, record, saved, 31);
    CALL1(DEPUTY, record);
    CALL3(PANEL_MESSAGE, ds[ACTIVE_SIDE], 2, text);
    opeu_copy_bytes(ds, saved, record, 31);
