/* One officer draw: under 10% the record (if any, and not already lost) is
 * hit unless flag 8 saves it half the time; under 5% the hit is fatal. */
static void officer_draw(uint8_t* ds, BattleEvent event, uint16_t bp,
                         uint8_t kind, uint16_t format, uint16_t killed_text) {
  uint16_t record, text = (uint16_t)(bp - 0x66);
  uint8_t  side = ds[ACTIVE_SIDE], draw;
  draw          = (uint8_t)CALL1(RAND, 100);
  if (draw >= 10)
    return;
  record = kind ? opeu_find_side_record(ds, side, kind)
                : opeu_find_group_record(ds, side, ds[ACTIVE_GROUP]);
  if (!record || (ds[(uint16_t)(record + 0x1e)] & 0x80))
    return;
  if ((ds[(uint16_t)(record + 0x1e)] & 8) && CALL1(RAND, 100) < 50)
    return;
  if (kind)
    call(ds, event, REQUEST_FORMAT, 6, text, format, COLOR(side),
         word_at(ds, (uint16_t)(SIDE_NAMES + side * 2)), record,
         (uint16_t)(draw >= 5 ? killed_text + 11 : killed_text), 0);
  else
    call(ds, event, REQUEST_FORMAT, 7, text, format, COLOR(side),
         word_at(ds, (uint16_t)(SIDE_NAMES + side * 2)),
         (uint16_t)(ds[ACTIVE_GROUP] + 1), record,
         (uint16_t)(draw >= 5 ? killed_text + 11 : killed_text));
  opeu_battle_officer_hit(ds, event, (uint16_t)(bp - 0x68 - 4), record, text,
                          draw < 5);
}

void opeu_battle_officer_losses(uint8_t* ds, BattleEvent event, uint16_t sp) {
  uint16_t bp = (uint16_t)(sp - 2);
  officer_draw(ds, event, bp, 0, 0xb91e, 0xb907);
  if (opeu_unit_group_index(opeu_find_side_selected_unit(
          ds, ds[ACTIVE_SIDE])) != ds[ACTIVE_GROUP])
    return;
  officer_draw(ds, event, bp, 1, 0xb95c, 0xb945);
  officer_draw(ds, event, bp, 3, 0xb993, 0xb97c);
  officer_draw(ds, event, bp, 2, 0xb9c7, 0xb9b0);
}

uint16_t opeu_battle_side_commands(const uint8_t* ds) {
  uint8_t side = ds[ACTIVE_SIDE];
  return word_at(ds, (uint16_t)(BATTLE_COMMAND + side * 2)) &&
         word_at(ds, (uint16_t)(SIDE_CONTROL + side * 2)) == 1;
}

void opeu_battle_hq_shaken(uint8_t* ds, BattleEvent event, uint16_t unit) {
  uint16_t a;
  for (a = word_at(ds, unit); a; a = word_at(ds, a))
    opeu_sub_byte((uint16_t)(CALL1(RAND, 3) + 2), &ds[(uint16_t)(a + 9)]);
}

void opeu_battle_hq_lost(uint8_t* ds, BattleEvent event, uint16_t sp) {
  ds[ACTIVE_SIDE]  = (uint8_t)CALL1(UNIT_SIDE, word_at(ds, LOST_UNIT));
  ds[ACTIVE_GROUP] = opeu_unit_group_index(word_at(ds, LOST_UNIT));
  if (word_at(ds, LOST_ELEMENT)) {
    if (opeu_battle_side_commands(ds))
      opeu_battle_pick_hq(ds, event, (uint16_t)(sp - 4));
    else
      opeu_battle_auto_hq(ds, event, (uint16_t)(sp - 4));
    opeu_battle_hq_shaken(ds, event, word_at(ds, LOST_UNIT));
  }
  if (ds[(uint16_t)(word_at(ds, LOST_UNIT) + 0x15)] & 1)
    opeu_battle_officer_losses(ds, event, (uint16_t)(sp - 4));
}
